// Ugyanaz a szezon- es hoszt-logika, mint a Slate Builder Config
// node-jaban. A KET HOSZT kulon rate-limit savon fut: 2026-09-08-an
// a www 503-at adott (Retry-After: 348), mikozben a www nelkuli
// valtozat 999/1000 kvotaval ment. Egy hoszt = egyetlen hibapont.
//
// Itt CSAK a FOLYO szezon kell: a szelvenyek mindig a kozeljovore
// szolnak, nem tavalyi meccsekre.
const NOW = new Date();
const y = NOW.getUTCFullYear(), mo = NOW.getUTCMonth() + 1;
const startYear = mo >= 8 ? y : y - 1;
const sc = yr => String(yr % 100).padStart(2, '0') + String((yr + 1) % 100).padStart(2, '0');
const SEASON = sc(startYear);

// A liganev UGYANAZ a string, amit a slate a league mezobe ir -
// ezen parosul az eredmeny a labhoz.
const LEAGUES = [
  { code: 'E0',  name: 'Premier League' },
  { code: 'SP1', name: 'La Liga' },
  { code: 'D1',  name: 'Bundesliga' },
  { code: 'I1',  name: 'Serie A' },
  { code: 'F1',  name: 'Ligue 1' },
];
const HOSTS = ['www.football-data.co.uk', 'football-data.co.uk'];

const out = [];
for (const lg of LEAGUES) {
  for (const host of HOSTS) {
    out.push({ json: {
      url: `https://${host}/mmz4281/${SEASON}/${lg.code}.csv`,
      host, key: lg.code, league: lg.code, league_name: lg.name, season: SEASON,
    }});
  }
}
return out;

// ===================== MEGOSZTOTT LOGIKA =====================
// Szo szerint a scripts/betting-research/teams.js + settle.js tartalma.
// A require/module.exports kivagva; egyebkent karakterre azonos azzal,
// amit a settle_test.js 79 teszten, valos adaton atvitt.
// Ha itt valtoztatsz, a scriptben IS valtoztass - vagy futtasd ujra a
// sync ellenorzest (settle_test.js osszeveti a ket ALIAS tablat).

// Csapatnev-parositas: a football-data.co.uk CSV nevei <-> The Odds API nevei.
//
// EZ A TABLA A FORRAS. Szo szerint kimasolva a "Generate Legs" node-bol
// (Betting Slate Builder), es a "Settle Legs" node ugyanezt hasznalja.
// Ket kezzel tartott kopia elkerulhetetlenul elcsuszik: az elso valtozatban
// 67 bejegyzes volt itt a 122 helyett, es az Espanyol (a CSV-ben "Espanol")
